const err = $json.execution?.error || {};
const wf = $json.workflow || {};
const execId = $json.execution?.id || 'unknown';

const wfName = wf.name || 'Unknown Workflow';
const nodeName = err.node?.name || 'Unknown Node';
const errMsg = err.message || 'Unknown error occurred';

// Ekstrak business key (order_id atau merchant_id)
let businessKey = 'N/A';
const fullStr = JSON.stringify($json);
const orderMatch = fullStr.match(/(?:order_id|orderId|order)["']?\s*[:=]\s*["']?(HM-[A-Za-z0-9-]+)/i) || errMsg.match(/(HM-[A-Za-z0-9-]+)/i);
const merchantMatch = fullStr.match(/(?:merchant_id|merchantId|merchant)["']?\s*[:=]\s*["']?(M0[0-9]{2})/i) || errMsg.match(/(M0[0-9]{2})/i);

if (orderMatch) {
  businessKey = orderMatch[1];
} else if (merchantMatch) {
  businessKey = merchantMatch[1];
} else {
  const runData = $json.execution?.data?.resultData?.runData;
  if (runData) {
    const runStr = JSON.stringify(runData);
    const m1 = runStr.match(/(HM-[A-Za-z0-9-]+)/);
    const m2 = runStr.match(/(M0[0-9]{2})/);
    if (m1) businessKey = m1[1];
    else if (m2) businessKey = m2[1];
  }
}
if (businessKey === 'N/A') {
  businessKey = `EXEC-${execId}`;
}

const alertText = `🚨 *H8Mart Ops Incident Alert*\n` +
  `*Workflow:* ${wfName}\n` +
  `*Node:* ${nodeName}\n` +
  `*Business Key:* ${businessKey}\n` +
  `*Execution ID:* ${execId}\n` +
  `*Error:* ${errMsg}\n` +
  `*Time:* ${new Date().toISOString()}`;

return [{
  json: {
    workflow_name: wfName,
    node_name: nodeName,
    execution_id: execId,
    business_key: businessKey,
    error_message: errMsg,
    alert_text: alertText
  }
}];
